const table = {};
function put(op, tag, fn) {
  table[op + '/' + tag] = fn;
}
function get(op, tag) {
  return table[op + '/' + tag];
}

put('real-part', 'rectangular', (z) => z.real);
put('real-part', 'polar', (z) => z.magnitude * Math.cos(z.angle));

function applyGeneric(op, tag, z) {
  return get(op, tag)(z);
}

console.log(applyGeneric('real-part', 'rectangular', { real: 3, imag: 4 }));

